from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    fill = counts.most_common(1)[0][0]
    rows = [r for r in range(h) if all(v != fill for v in grid[r])]
    cols = [c for c in range(w) if all(grid[r][c] != fill for r in range(h))]
    if len(rows) < 2 or len(cols) < 2:
        return [row[:] for row in grid]
    intersections = {(r,c) for r in rows for c in cols}
    line_vals = [grid[r][c] for r in rows for c in range(w) if (r,c) not in intersections and grid[r][c] != fill]
    line_vals += [grid[r][c] for c in cols for r in range(h) if (r,c) not in intersections and grid[r][c] != fill]
    line_color = Counter(line_vals).most_common(1)[0][0]
    out = []
    for r0,r1 in zip(rows, rows[1:]):
        row=[]
        for c0,c1 in zip(cols, cols[1:]):
            corners=[grid[r0][c0],grid[r0][c1],grid[r1][c0],grid[r1][c1]]
            row.append(corners[0] if corners.count(corners[0]) == 4 and corners[0] != fill and corners[0] != line_color else fill)
        out.append(row)
    while out and all(v == fill for v in out[0]): out.pop(0)
    while out and all(v == fill for v in out[-1]): out.pop()
    if out:
        while out and all(row[0] == fill for row in out):
            for row in out: row.pop(0)
        while out and all(row[-1] == fill for row in out):
            for row in out: row.pop()
    return out

